<template>
  <div class="page-container sil-page"><div class="page-head"><div><h2>青贮申报审核</h2><p>省、市、县管理角色按数据范围审核申报，支持通过、退回补正、驳回并保留留痕。</p></div><el-tag type="warning">待审核 {{ rows.filter(r => r.status === 'pending').length }} 条</el-tag></div><div class="panel"><el-form :inline="true" class="filters"><el-form-item label="年份"><el-select v-model="filters.year" clearable placeholder="全部" style="width:120px"><el-option :value="2027" label="2027年"/><el-option :value="2026" label="2026年"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filters.status" placeholder="待审核" clearable style="width:130px"><el-option label="待审核" value="pending"/><el-option label="已备案" value="filed"/><el-option label="退回补正" value="returned"/><el-option label="已驳回" value="rejected"/></el-select></el-form-item><el-form-item label="关键词"><el-input v-model="filters.keyword" clearable placeholder="主体、品种或编号"/></el-form-item><el-button type="primary" @click="load">查询</el-button><el-button @click="reset">重置</el-button></el-form><el-table :data="filteredRows" stripe border><el-table-column prop="id" label="申报编号" width="165"/><el-table-column prop="subjectName" label="申报主体" min-width="190"/><el-table-column prop="cropName" label="品种" width="110"/><el-table-column prop="area" label="面积（亩）" width="105" align="right"/><el-table-column prop="expectedYield" label="预计产量（吨）" width="125" align="right"/><el-table-column prop="createdAt" label="提交时间" width="110"/><el-table-column prop="status" label="状态" width="95"><template #default="{row}"><el-tag size="small" :type="tagType(row.status)">{{ statusName(row.status) }}</el-tag></template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">{{ row.status === 'pending' ? '审核处理' : '查看留痕' }}</el-button><el-button link @click="showTrail(row)">留痕</el-button></template></el-table-column></el-table><el-empty v-if="!filteredRows.length" description="暂无审核数据"/></div><el-dialog v-model="visible" title="申报审核详情" width="860px"><template v-if="current"><el-descriptions :column="3" border><el-descriptions-item label="申报编号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="申报主体">{{ current.subjectName }}</el-descriptions-item><el-descriptions-item label="年度">{{ current.year }}年</el-descriptions-item><el-descriptions-item label="种植品种">{{ current.cropName }} / {{ current.variety }}</el-descriptions-item><el-descriptions-item label="申报面积">{{ current.area }} 亩</el-descriptions-item><el-descriptions-item label="地块位置">{{ current.plotIds?.join('、') || '未填报' }}</el-descriptions-item><el-descriptions-item label="预计产量">{{ current.expectedYield }} 吨</el-descriptions-item><el-descriptions-item label="收储价格">{{ current.price }} 元/吨</el-descriptions-item><el-descriptions-item label="备案编号" :span="3">{{ current.filedNo || '审核通过后生成' }}</el-descriptions-item></el-descriptions><div class="sub-title">审核留痕</div><el-timeline><el-timeline-item v-for="(item,index) in current.auditTrail" :key="index" :timestamp="item.time">{{ item.action }}<span class="trail-user">{{ item.user }}</span><div v-if="item.opinion" class="trail-opinion">{{ item.opinion }}</div></el-timeline-item></el-timeline><el-input v-if="current.status === 'pending'" v-model="opinion" type="textarea" :rows="3" placeholder="填写审核意见；退回或驳回时必填"/></template><template #footer><el-button @click="visible=false">关闭</el-button><template v-if="current?.status === 'pending'"><el-button type="warning" @click="audit('return')">退回补正</el-button><el-button type="danger" @click="audit('reject')">驳回</el-button><el-button type="primary" @click="audit('pass')">通过备案</el-button></template></template></el-dialog></div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { fetchDeclarations, auditDeclaration } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const current = ref(null); const visible = ref(false); const opinion = ref(''); const filters = reactive({ year: '', status: 'pending', keyword: '' }); const statusName = (s) => ({ pending: '待审核', filed: '已备案', returned: '退回补正', rejected: '已驳回' }[s] || s); const tagType = (s) => ({ pending: 'warning', filed: 'success', returned: 'warning', rejected: 'danger' }[s] || 'info'); const filteredRows = computed(() => rows.value.filter((r) => (!filters.year || r.year === filters.year) && (!filters.status || r.status === filters.status) && (!filters.keyword || `${r.id}${r.subjectName}${r.cropName}${r.variety}`.includes(filters.keyword)))); const load = async () => { rows.value = await fetchDeclarations(userStore.role) }; const reset = () => { Object.assign(filters, { year: '', status: 'pending', keyword: '' }); load() }; const open = (row) => { current.value = row; opinion.value = ''; visible.value = true }; const showTrail = (row) => open(row)
const audit = async (action) => { if (action !== 'pass' && !opinion.value.trim()) return ElMessage.warning('请填写处理意见'); try { await ElMessageBox.confirm(`确认${action === 'pass' ? '通过备案' : action === 'return' ? '退回补正' : '驳回'}该申报吗？`, '审核确认', { type: action === 'pass' ? 'success' : 'warning' }) } catch { return } const result = await auditDeclaration(current.value.id, action, opinion.value, userStore.regionName); if (!result.success) return ElMessage.error('审核失败'); ElMessage.success('审核结果已保存'); visible.value = false; load() }
onMounted(load)
</script>
<style scoped lang="scss">.sil-page{overflow:auto}.page-head{display:flex;justify-content:space-between;margin-bottom:14px}.page-head h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px}.sub-title{margin:18px 0 10px;padding-left:8px;border-left:3px solid var(--ah-primary);font-weight:600}.trail-user{margin-left:12px;color:#8492a6}.trail-opinion{margin-top:4px;color:#667085}</style>